import { themeDeclarations } from './theme.ts';
import type { Theme } from './theme.ts';

const lines = (theme: Theme, indent: string): string[] => themeDeclarations(theme).map(([n, v]) => `${indent}${n}: ${v};`);

/** CSS that sets the contract variables for both themes. Same selectors as the tokens CSS. */
export function toThemeCss(light: Theme, dark: Theme): string {
  return [
    '/* Generated by @ds-scope/theme. Do not edit. */',
    '',
    ':root,',
    '[data-theme="light"] {',
    '  color-scheme: light;',
    ...lines(light, '  '),
    '}',
    '',
    '[data-theme="dark"] {',
    '  color-scheme: dark;',
    ...lines(dark, '  '),
    '}',
    '',
    '@media (prefers-color-scheme: dark) {',
    '  :root:not([data-theme="light"]) {',
    '    color-scheme: dark;',
    ...lines(dark, '    '),
    '  }',
    '}',
    '',
  ].join('\n');
}
